You can use this patch:
```patch
From 9de2b348bf2c80d6bdcf70d9fa0436a6dc641529 Mon Sep 17 00:00:00 2001
From: kobewi <kobewi4e@gmail.com>
Date: Sat, 29 Aug 2026 14:41:40 +0200
Subject: [PATCH] Fix button size update

---
 editor/editor_log.cpp | 32 +++++++++++---------------------
 editor/editor_log.h   |  4 +++-
 2 files changed, 14 insertions(+), 22 deletions(-)

diff --git a/editor/editor_log.cpp b/editor/editor_log.cpp
index 63934c70b7..dedb5f987b 100644
--- a/editor/editor_log.cpp
+++ b/editor/editor_log.cpp
@@ -108,21 +108,6 @@ void EditorLog::_update_theme() {
 	log->add_theme_font_size_override("mono_font_size", font_size);
 	log->end_bulk_theme_override();
 
-	const String wide_text = "0000";
-
-	Button *button = type_filter_map[MSG_TYPE_STD]->toggle_button;
-	button->set_button_icon(get_editor_theme_icon(SNAME("Popup")));
-	button->set_custom_minimum_size(Vector2(button->get_minimum_size_for_text_and_icon(wide_text, button->get_button_icon()).x, 0));
-	button = type_filter_map[MSG_TYPE_ERROR]->toggle_button;
-	button->set_button_icon(get_editor_theme_icon(SNAME("StatusError")));
-	button->set_custom_minimum_size(Vector2(button->get_minimum_size_for_text_and_icon(wide_text, button->get_button_icon()).x, 0));
-	button = type_filter_map[MSG_TYPE_WARNING]->toggle_button;
-	button->set_button_icon(get_editor_theme_icon(SNAME("StatusWarning")));
-	button->set_custom_minimum_size(Vector2(button->get_minimum_size_for_text_and_icon(wide_text, button->get_button_icon()).x, 0));
-	button = type_filter_map[MSG_TYPE_EDITOR]->toggle_button;
-	button->set_button_icon(get_editor_theme_icon(SNAME("Edit")));
-	button->set_custom_minimum_size(Vector2(button->get_minimum_size_for_text_and_icon(wide_text, button->get_button_icon()).x, 0));
-
 	clear_button->set_button_icon(get_editor_theme_icon(SNAME("Clear")));
 	collapse_button->set_button_icon(get_editor_theme_icon(SNAME("CombineLines")));
 	search_box->set_right_icon(get_editor_theme_icon(SNAME("Search")));
@@ -134,6 +119,11 @@ void EditorLog::_update_theme() {
 	theme_cache.message_color = get_theme_color(SceneStringName(font_color), EditorStringName(Editor)) * Color(1, 1, 1, 0.6);
 }
 
+void EditorLog::_update_button_minimum_size(Button *p_button, const StringName &p_icon_name) {
+	p_button->set_button_icon(get_editor_theme_icon(p_icon_name));
+	p_button->set_custom_minimum_size(Vector2(p_button->get_minimum_size_for_text_and_icon("0000", p_button->get_button_icon()).x, 0));
+}
+
 void EditorLog::_editor_settings_changed() {
 	int new_line_limit = int(EDITOR_GET("run/output/max_lines"));
 	if (new_line_limit != line_limit) {
@@ -156,8 +146,8 @@ void EditorLog::_notification(int p_what) {
 		} break;
 
 		case NOTIFICATION_THEME_CHANGED: {
-			callable_mp(this, &EditorLog::_update_theme).call_deferred();
-			callable_mp(this, &EditorLog::_rebuild_log).call_deferred();
+			_update_theme();
+			_rebuild_log();
 		} break;
 	}
 }
@@ -566,23 +556,23 @@ EditorLog::EditorLog() {
 
 	// Message Type Filters.
 	LogFilter *std_filter = memnew(LogFilter(MSG_TYPE_STD));
-	std_filter->initialize_button(TTRC("Standard Messages"), TTRC("Toggle visibility of standard output messages."), callable_mp(this, &EditorLog::_set_filter_active));
+	std_filter->initialize_button(TTRC("Standard Messages"), TTRC("Toggle visibility of standard output messages."), callable_mp(this, &EditorLog::_set_filter_active), callable_mp(this, &EditorLog::_update_button_minimum_size).bind(StringName("Popup")));
 	hbox->add_child(std_filter->toggle_button);
 	type_filter_map.insert(MSG_TYPE_STD, std_filter);
 	type_filter_map.insert(MSG_TYPE_STD_RICH, std_filter);
 
 	LogFilter *error_filter = memnew(LogFilter(MSG_TYPE_ERROR));
-	error_filter->initialize_button(TTRC("Errors"), TTRC("Toggle visibility of errors."), callable_mp(this, &EditorLog::_set_filter_active));
+	error_filter->initialize_button(TTRC("Errors"), TTRC("Toggle visibility of errors."), callable_mp(this, &EditorLog::_set_filter_active), callable_mp(this, &EditorLog::_update_button_minimum_size).bind(StringName("StatusError")));
 	hbox->add_child(error_filter->toggle_button);
 	type_filter_map.insert(MSG_TYPE_ERROR, error_filter);
 
 	LogFilter *warning_filter = memnew(LogFilter(MSG_TYPE_WARNING));
-	warning_filter->initialize_button(TTRC("Warnings"), TTRC("Toggle visibility of warnings."), callable_mp(this, &EditorLog::_set_filter_active));
+	warning_filter->initialize_button(TTRC("Warnings"), TTRC("Toggle visibility of warnings."), callable_mp(this, &EditorLog::_set_filter_active), callable_mp(this, &EditorLog::_update_button_minimum_size).bind(StringName("StatusWarning")));
 	hbox->add_child(warning_filter->toggle_button);
 	type_filter_map.insert(MSG_TYPE_WARNING, warning_filter);
 
 	LogFilter *editor_filter = memnew(LogFilter(MSG_TYPE_EDITOR));
-	editor_filter->initialize_button(TTRC("Editor Messages"), TTRC("Toggle visibility of editor messages."), callable_mp(this, &EditorLog::_set_filter_active));
+	editor_filter->initialize_button(TTRC("Editor Messages"), TTRC("Toggle visibility of editor messages."), callable_mp(this, &EditorLog::_set_filter_active), callable_mp(this, &EditorLog::_update_button_minimum_size).bind(StringName("Edit")));
 	hbox->add_child(editor_filter->toggle_button);
 	type_filter_map.insert(MSG_TYPE_EDITOR, editor_filter);
 
diff --git a/editor/editor_log.h b/editor/editor_log.h
index f8d0b508b9..8edddec565 100644
--- a/editor/editor_log.h
+++ b/editor/editor_log.h
@@ -88,7 +88,7 @@ private:
 		MessageType type;
 		Button *toggle_button = nullptr;
 
-		void initialize_button(const String &p_name, const String &p_tooltip, Callable p_toggled_callback) {
+		void initialize_button(const String &p_name, const String &p_tooltip, const Callable &p_toggled_callback, const Callable &p_theme_changed_callback) {
 			toggle_button = memnew(Button);
 			toggle_button->set_toggle_mode(true);
 			toggle_button->set_pressed(true);
@@ -99,6 +99,7 @@ private:
 			toggle_button->set_theme_type_variation("EditorLogFilterButton");
 			// When toggled call the callback and pass the MessageType this button is for.
 			toggle_button->connect(SceneStringName(toggled), p_toggled_callback.bind(type));
+			toggle_button->connect(SceneStringName(theme_changed), p_theme_changed_callback.bind(toggle_button), CONNECT_DEFERRED);
 		}
 
 		int get_message_count() {
@@ -172,6 +173,7 @@ private:
 	void _load_state();
 
 	void _update_theme();
+	void _update_button_minimum_size(Button *p_button, const StringName &p_icon_name);
 	void _editor_settings_changed();
 
 protected:
-- 
2.55.0

```
However I had to use CONNECT_DEFERRED in the end, so it's only slightly better.
